/**
 * components/ui/action-menu.tsx
 *
 * Compact, viewport-aware action menu for table rows and tight layouts.
 */
import { effect, onCleanup, signal } from '@vorzelajs/core'
import { For, Show } from '@vorzelajs/dom'
import { accessorOf } from '~/hooks/index.ts'
import { useId } from '~/hooks/use-id.ts'
import { cx } from '~/lib/cx.ts'
import type { ReactNode } from '~/lib/types.ts'
import { Portal } from '~/components/primitives/portal.tsx'
import styles from './action-menu.module.scss'

const MARGIN = 8
const GAP = 4

export interface ActionMenuItem {
  /** Unique key */
  key: string
  /** Display label */
  label: string
  /** Leading icon — any JSX (e.g. <Pencil size={14} />) */
  icon?: ReactNode
  /** Trailing content — badge, shortcut hint, etc. */
  trailing?: ReactNode
  /** Renders in red / danger colours */
  danger?: boolean
  /** Greys out and blocks interaction */
  disabled?: boolean
  /** Renders a thin divider above this item */
  divider?: boolean
  /** Section label rendered above this item (replaces divider when set) */
  sectionLabel?: string
  /** Called when the item is clicked */
  onSelect?: () => void
}

export interface ActionMenuProps {
  /** Menu items */
  items: ActionMenuItem[] | (() => ActionMenuItem[])
  /** Replace the default ⋯ trigger with your own element */
  trigger?: ReactNode
  /** Preferred horizontal alignment of the panel relative to the trigger */
  align?: 'left' | 'right'
  /** Close the menu when an item is selected (default: true) */
  closeOnSelect?: boolean
  /** Controlled open state */
  open?: boolean | (() => boolean)
  onOpenChange?: (open: boolean) => void
  /** Extra class on the trigger wrapper */
  className?: string
  /** Extra class on the panel */
  panelClass?: string
  /** Accessible label for the default trigger button */
  triggerLabel?: string
}

interface PanelPos {
  x: number
  y: number
  direction: 'bottom' | 'top'
}

function computePanelPos(
  trigger: HTMLElement,
  panel: HTMLElement,
  align: 'left' | 'right',
): PanelPos {
  const triggerRect = trigger.getBoundingClientRect()
  const panelWidth = panel.offsetWidth
  const panelHeight = panel.offsetHeight
  const vw = window.innerWidth
  const vh = window.innerHeight

  const spaceBelow = vh - triggerRect.bottom - MARGIN
  const spaceAbove = triggerRect.top - MARGIN
  const direction: 'bottom' | 'top' =
    spaceBelow >= panelHeight + GAP || spaceBelow >= spaceAbove
      ? 'bottom'
      : 'top'

  const y =
    direction === 'bottom'
      ? triggerRect.bottom + GAP
      : triggerRect.top - panelHeight - GAP

  let x: number
  if (align === 'right') {
    x = triggerRect.right - panelWidth
    if (x < MARGIN) x = MARGIN
  } else {
    x = triggerRect.left
    if (x + panelWidth > vw - MARGIN) x = vw - panelWidth - MARGIN
  }

  return { x, y, direction }
}

function DotsIcon() {
  return (
    <svg
      width="15"
      height="15"
      viewBox="0 0 15 15"
      fill="currentColor"
      aria-hidden="true"
    >
      <circle cx="3" cy="7.5" r="1.25" />
      <circle cx="7.5" cy="7.5" r="1.25" />
      <circle cx="12" cy="7.5" r="1.25" />
    </svg>
  )
}

export function ActionMenu({
  items,
  trigger,
  align = 'right',
  closeOnSelect = true,
  open,
  onOpenChange,
  className,
  panelClass,
  triggerLabel = 'Open actions menu',
}: ActionMenuProps) {
  const [internalOpen, setInternalOpen] = signal(false)
  const controlledOpen = open === undefined ? null : accessorOf(open)
  const isOpen = (): boolean =>
    controlledOpen ? controlledOpen() : internalOpen()

  const setOpen = (value: boolean): void => {
    if (!controlledOpen) setInternalOpen(value)
    onOpenChange?.(value)
  }

  const [triggerNode, setTriggerNode] = signal<HTMLDivElement | null>(null)
  const [panelNode, setPanelNode] = signal<HTMLDivElement | null>(null)
  const panelId = useId('action-menu-panel')

  const [pos, setPos] = signal<PanelPos>({
    x: 0,
    y: 0,
    direction: 'bottom',
  })
  const [posReady, setPosReady] = signal(false)

  onCleanup(() => setTriggerNode(null))

  const recompute = (): void => {
    const wrapper = triggerNode()
    const panel = panelNode()
    if (!wrapper || !panel || typeof window === 'undefined') return

    const triggerElement =
      wrapper.querySelector<HTMLElement>('button, a, [role="button"]') ??
      wrapper
    setPos(computePanelPos(triggerElement, panel, align))
    setPosReady(true)
  }

  effect(() => {
    const openNow = isOpen()
    const wrapper = triggerNode()
    const panel = panelNode()

    if (!openNow) {
      setPosReady(false)
      return
    }

    if (!wrapper || !panel || typeof window === 'undefined') return

    const frame = requestAnimationFrame(recompute)
    onCleanup(() => cancelAnimationFrame(frame))
  })

  effect(() => {
    if (!isOpen() || typeof window === 'undefined') return

    const handler = (): void => recompute()
    window.addEventListener('scroll', handler, { passive: true, capture: true })
    window.addEventListener('resize', handler, { passive: true })
    onCleanup(() => {
      window.removeEventListener('scroll', handler, { capture: true })
      window.removeEventListener('resize', handler)
    })
  })

  effect(() => {
    if (!isOpen() || typeof document === 'undefined') return

    const handler = (event: MouseEvent): void => {
      const target = event.target as Node
      if (
        triggerNode()?.contains(target) ||
        panelNode()?.contains(target)
      ) {
        return
      }
      setOpen(false)
    }

    const id = setTimeout(
      () => document.addEventListener('mousedown', handler),
      0,
    )
    onCleanup(() => {
      clearTimeout(id)
      document.removeEventListener('mousedown', handler)
    })
  })

  effect(() => {
    if (!isOpen() || typeof document === 'undefined') return

    const focusableItems = (): HTMLElement[] =>
      Array.from(
        panelNode()?.querySelectorAll<HTMLElement>(
          '[role="menuitem"]:not([disabled])',
        ) ?? [],
      )

    const onKeyDown = (event: KeyboardEvent): void => {
      const focusable = focusableItems()
      const index = focusable.indexOf(
        document.activeElement as HTMLElement,
      )

      if (event.key === 'Escape') {
        event.preventDefault()
        setOpen(false)
        triggerNode()
          ?.querySelector<HTMLElement>('button, a, [tabindex]')
          ?.focus()
        return
      }
      if (event.key === 'ArrowDown') {
        event.preventDefault()
        focusable[(index + 1) % focusable.length]?.focus()
        return
      }
      if (event.key === 'ArrowUp') {
        event.preventDefault()
        focusable[
          (index - 1 + focusable.length) % focusable.length
        ]?.focus()
        return
      }
      if (event.key === 'Tab') {
        setOpen(false)
      }
    }

    document.addEventListener('keydown', onKeyDown)
    const frame = requestAnimationFrame(() =>
      focusableItems()[0]?.focus(),
    )
    onCleanup(() => {
      cancelAnimationFrame(frame)
      document.removeEventListener('keydown', onKeyDown)
    })
  })

  const handleSelect = (item: ActionMenuItem): void => {
    if (item.disabled) return
    item.onSelect?.()
    if (closeOnSelect) setOpen(false)
  }

  return (
    <>
      <div
        ref={(element) => setTriggerNode(element as HTMLDivElement)}
        className={cx(styles.wrap, className)}
        onClick={(event) => {
          if (!trigger) return
          event.stopPropagation()
          setOpen(!isOpen())
        }}
      >
        {trigger ?? (
          <button
            type="button"
            aria-label={triggerLabel}
            aria-haspopup="menu"
            aria-expanded={() => String(isOpen())}
            aria-controls={() => (isOpen() ? panelId : undefined)}
            onClick={(event) => {
              event.stopPropagation()
              setOpen(!isOpen())
            }}
            className={() =>
              cx(styles.trigger, isOpen() && styles.triggerOpen)
            }
          >
            <DotsIcon />
          </button>
        )}
      </div>

      <Show when={isOpen}>
        {() => {
          const panel = (
            <Portal>
              <div
                ref={(element) => setPanelNode(element as HTMLDivElement)}
                id={panelId}
                role="menu"
                aria-label={triggerLabel}
                aria-orientation="vertical"
                data-dir={() => pos().direction}
                className={cx(styles.panel, panelClass)}
                style={() => ({
                  left: `${pos().x}px`,
                  top: `${pos().y}px`,
                  visibility: posReady() ? 'visible' : 'hidden',
                })}
              >
                <For
                  each={accessorOf<ActionMenuItem[]>(items)}
                  key={(item) => item.key}
                >
                  {(item) => [
                    item.sectionLabel ? (
                      <p className={styles.sectionLabel}>
                        {item.sectionLabel}
                      </p>
                    ) : null,

                    item.divider && !item.sectionLabel ? (
                      <div className={styles.divider} role="separator" />
                    ) : null,

                    <button
                      type="button"
                      role="menuitem"
                      disabled={item.disabled}
                      className={cx(
                        styles.item,
                        item.danger && styles.itemDanger,
                      )}
                      onClick={() => handleSelect(item)}
                    >
                      {item.icon ? (
                        <span className={styles.itemIcon}>{item.icon}</span>
                      ) : (
                        <span
                          className={cx(
                            styles.itemIcon,
                            styles.itemIconEmpty,
                          )}
                        />
                      )}

                      <span className={styles.itemLabel}>{item.label}</span>

                      {item.trailing ? (
                        <span className={styles.itemTrailing}>
                          {item.trailing}
                        </span>
                      ) : null}
                    </button>,
                  ]}
                </For>
              </div>
            </Portal>
          )

          onCleanup(() => setPanelNode(null))
          return panel
        }}
      </Show>
    </>
  )
}

@use 'styles' as vz;

.wrap {
  display: inline-flex;
  width: fit-content;
}

.trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: vz.space(7);
  height: vz.space(7);
  padding: 0;
  border: 0;
  border-radius: vz.radius('lg');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    width: 15px;
    height: 15px;
    pointer-events: none;
  }
}

.trigger-open {
  background: vz.color('muted');
  color: vz.color('foreground');
}

.panel {
  @include vz.raised(2);

  position: fixed;
  z-index: vz.z('dropdown');
  min-width: 172px;
  padding: vz.space(1);
  border-radius: vz.radius('xl');
  font-size: 13px;
}

.panel[data-dir='bottom'] {
  animation: vz-action-menu-in-down vz.duration('fast') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.panel[data-dir='top'] {
  animation: vz-action-menu-in-up vz.duration('fast') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.section-label {
  margin: 0;
  padding: 6px 10px 2px;
  color: vz.color('muted-foreground');
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  user-select: none;
}

.divider {
  height: 1px;
  margin: vz.space(1) 0;
  background: vz.color('border');
}

.item {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  width: 100%;
  padding: 6px 10px;
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('foreground');
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, -2px, 0.6);

  &:focus-visible {
    background: vz.color('accent');
  }

  @include vz.disabled {
    opacity: 0.6;
    cursor: not-allowed;
    pointer-events: none;
  }
}

.item-danger {
  color: vz.color('destructive');

  @include vz.hover {
    background: vz.color('destructive', 0.1);
  }

  &:focus-visible {
    background: vz.color('destructive', 0.1);
  }
}

.item-danger .item-icon {
  color: vz.color('destructive');
}

.item-icon {
  display: inline-flex;
  width: 1rem;
  flex: none;
  align-items: center;
  justify-content: center;
  opacity: 0.75;
}

.item-icon-empty {
  opacity: 0;
}

.item-label {
  flex: 1;
}

.item-trailing {
  flex: none;
  opacity: 0.5;
  font-size: 11px;
}

@keyframes vz-action-menu-in-down {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(-4px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes vz-action-menu-in-up {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(4px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
